## 긴 파일 예시

다음과 같은 **500줄 파일**도 완벽히 파싱 가능:

```javascript
// game.free - 간단한 게임 로직
const GRID_SIZE = 10;
const MAX_PLAYERS = 4;

defn createPlayer(id, name) {
  return {
    id: id,
    name: name,
    score: 0,
    active: true,
    inventory: [],
    position: {x: 0, y: 0}
  };
}

defn initializeGame() {
  let players = [];
  let i = 0;
  while (i < MAX_PLAYERS) {
    players[i] = createPlayer(i, "Player" + i);
    i = i + 1;
  }
  return {
    players: players,
    grid: createGrid(GRID_SIZE),
    gameState: "running"
  };
}

defn createGrid(size) {
  let grid = [];
  let i = 0;
  while (i < size) {
    grid[i] = [];
    let j = 0;
    while (j < size) {
      grid[i][j] = 0;
      j = j + 1;
    }
    i = i + 1;
  }
  return grid;
}

defn movePlayer(player, dx, dy) {
  let newX = player.position.x + dx;
  let newY = player.position.y + dy;

  if (newX >= 0 && newX < GRID_SIZE && newY >= 0 && newY < GRID_SIZE) {
    player.position.x = newX;
    player.position.y = newY;
    return true;
  }
  return false;
}

defn gameLoop(game) {
  let running = true;
  while (running) {
    for (let player of game.players) {
      if (player.active) {
        // ... 게임 로직
      }
    }
    // ... 렌더링, 입력 처리 등
  }
}

// ... 더 많은 함수들

let game = initializeGame();
gameLoop(game);
```

