## 1️⃣ **타입 시스템 설계**

### A. 기본 타입

```typescript
type Type =
  | "number"                    // 숫자: 123, 3.14
  | "string"                    // 문자열: "hello"
  | "boolean"                   // 불리언: true, false
  | "null"                      // null
  | "undefined"                 // undefined
  | ArrayType                   // 배열: number[], string[]
  | ObjectType                  // 객체: {x: number, y: number}
  | FunctionType                // 함수: (number, number) => number
  | UnionType                   // 합집합: number | string
  | "any"                       // 임의의 타입
  | "never";                    // 도달 불가능

interface ArrayType {
  kind: "array";
  elementType: Type;
}

interface ObjectType {
  kind: "object";
  properties: Map<string, Type>;
}

interface FunctionType {
  kind: "function";
  params: Type[];
  returnType: Type;
}

interface UnionType {
  kind: "union";
  types: Type[];
}
```

### B. 타입 주석 문법

```javascript
