/**
 * Phase 13: Standard Library - Array Methods
 *
 * 배열 메서드 표준 라이브러리 구현
 * - map, filter, reduce, forEach (고차 함수)
 * - find, indexOf, includes (탐색)
 * - some, every (집계)
 * - length, reverse, sort (기본)
 */

/**
 * 배열 메서드들
 */
export class ArrayMethods {
  /**
   * map(arr, fn) - 각 요소에 함수 적용하여 새 배열 생성
   */
  static map(arr: any[], fn: (value: any, index?: number) => any): any[] {
    const result: any[] = [];
    for (let i = 0; i < arr.length; i++) {
      result.push(fn(arr[i], i));
    }
    return result;
  }

  /**
   * filter(arr, predicate) - 조건에 맞는 요소만 필터링
   */
  static filter(arr: any[], predicate: (value: any, index?: number) => boolean): any[] {
    const result: any[] = [];
    for (let i = 0; i < arr.length; i++) {
      if (predicate(arr[i], i)) {
        result.push(arr[i]);
      }
    }
    return result;
  }

  /**
   * reduce(arr, fn, initialValue) - 배열을 단일 값으로 축약
   */
  static reduce(
    arr: any[],
    fn: (accumulator: any, currentValue: any, index?: number) => any,
    initialValue: any
  ): any {
    let accumulator = initialValue;
    for (let i = 0; i < arr.length; i++) {
      accumulator = fn(accumulator, arr[i], i);
    }
    return accumulator;
  }

  /**
   * forEach(arr, fn) - 각 요소에 대해 함수 실행 (부작용)
   */
  static forEach(arr: any[], fn: (value: any, index?: number) => void): void {
    for (let i = 0; i < arr.length; i++) {
      fn(arr[i], i);
    }
  }

  /**
   * find(arr, predicate) - 조건을 만족하는 첫 요소 반환
   */
  static find(arr: any[], predicate: (value: any, index?: number) => boolean): any {
    for (let i = 0; i < arr.length; i++) {
      if (predicate(arr[i], i)) {
        return arr[i];
      }
    }
    return undefined;
  }

  /**
   * findIndex(arr, predicate) - 조건을 만족하는 첫 요소의 인덱스
   */
  static findIndex(arr: any[], predicate: (value: any, index?: number) => boolean): number {
    for (let i = 0; i < arr.length; i++) {
      if (predicate(arr[i], i)) {
        return i;
      }
    }
    return -1;
  }

  /**
   * indexOf(arr, searchElement) - 요소의 인덱스 반환
   */
  static indexOf(arr: any[], searchElement: any, fromIndex: number = 0): number {
    for (let i = fromIndex; i < arr.length; i++) {
      if (arr[i] === searchElement) {
        return i;
      }
    }
    return -1;
  }

  /**
   * lastIndexOf(arr, searchElement) - 요소의 마지막 인덱스 반환
   */
  static lastIndexOf(arr: any[], searchElement: any, fromIndex?: number): number {
    const length = arr.length;
    let i = fromIndex !== undefined ? fromIndex : length - 1;

    if (i < 0) {
      i = Math.max(0, length + i);
    } else if (i >= length) {
      i = length - 1;
    }

    for (; i >= 0; i--) {
      if (arr[i] === searchElement) {
        return i;
      }
    }
    return -1;
  }

  /**
   * includes(arr, searchElement) - 요소 포함 여부
   */
  static includes(arr: any[], searchElement: any, fromIndex: number = 0): boolean {
    return this.indexOf(arr, searchElement, fromIndex) !== -1;
  }

  /**
   * some(arr, predicate) - 조건을 만족하는 요소가 있는지 확인
   */
  static some(arr: any[], predicate: (value: any, index?: number) => boolean): boolean {
    for (let i = 0; i < arr.length; i++) {
      if (predicate(arr[i], i)) {
        return true;
      }
    }
    return false;
  }

  /**
   * every(arr, predicate) - 모든 요소가 조건을 만족하는지 확인
   */
  static every(arr: any[], predicate: (value: any, index?: number) => boolean): boolean {
    for (let i = 0; i < arr.length; i++) {
      if (!predicate(arr[i], i)) {
        return false;
      }
    }
    return true;
  }

  /**
   * length(arr) - 배열의 길이
   */
  static length(arr: any[]): number {
    return arr.length;
  }

  /**
   * reverse(arr) - 배열을 역순으로 정렬
   */
  static reverse(arr: any[]): any[] {
    const result = [...arr];
    let left = 0;
    let right = result.length - 1;

    while (left < right) {
      const temp = result[left];
      result[left] = result[right];
      result[right] = temp;
      left++;
      right--;
    }

    return result;
  }

  /**
   * sort(arr, compareFn) - 배열 정렬
   */
  static sort(arr: any[], compareFn?: (a: any, b: any) => number): any[] {
    const result = [...arr];

    // 기본 정렬: 숫자 오름차순
    if (!compareFn) {
      compareFn = (a: any, b: any) => {
        if (typeof a === "number" && typeof b === "number") {
          return a - b;
        }
        if (typeof a === "string" && typeof b === "string") {
          return a < b ? -1 : a > b ? 1 : 0;
        }
        return 0;
      };
    }

    // 간단한 버블 정렬
    for (let i = 0; i < result.length; i++) {
      for (let j = 0; j < result.length - i - 1; j++) {
        if (compareFn(result[j], result[j + 1]) > 0) {
          const temp = result[j];
          result[j] = result[j + 1];
          result[j + 1] = temp;
        }
      }
    }

    return result;
  }

  /**
   * join(arr, separator) - 배열 요소를 문자열로 연결
   */
  static join(arr: any[], separator: string = ","): string {
    const parts: string[] = [];
    for (let i = 0; i < arr.length; i++) {
      const val = arr[i];
      if (val === null || val === undefined) {
        parts.push("");
      } else {
        parts.push(String(val));
      }
    }
    return parts.join(separator);
  }

  /**
   * push(arr, ...items) - 배열 끝에 요소 추가
   */
  static push(arr: any[], ...items: any[]): number {
    for (const item of items) {
      arr.push(item);
    }
    return arr.length;
  }

  /**
   * pop(arr) - 배열 끝에서 요소 제거
   */
  static pop(arr: any[]): any {
    return arr.pop();
  }

  /**
   * shift(arr) - 배열 시작에서 요소 제거
   */
  static shift(arr: any[]): any {
    return arr.shift();
  }

  /**
   * unshift(arr, ...items) - 배열 시작에 요소 추가
   */
  static unshift(arr: any[], ...items: any[]): number {
    for (let i = items.length - 1; i >= 0; i--) {
      arr.unshift(items[i]);
    }
    return arr.length;
  }

  /**
   * slice(arr, start, end) - 배열의 일부를 추출
   */
  static slice(arr: any[], start: number = 0, end?: number): any[] {
    const length = arr.length;
    if (start < 0) {
      start = Math.max(0, length + start);
    }

    if (end === undefined) {
      end = length;
    } else if (end < 0) {
      end = Math.max(0, length + end);
    }

    const result: any[] = [];
    for (let i = start; i < end && i < length; i++) {
      result.push(arr[i]);
    }
    return result;
  }

  /**
   * concat(arr, ...items) - 배열 연결
   */
  static concat(arr: any[], ...items: any[]): any[] {
    const result = [...arr];
    for (const item of items) {
      if (Array.isArray(item)) {
        result.push(...item);
      } else {
        result.push(item);
      }
    }
    return result;
  }

  /**
   * flatten(arr, depth) - 배열 평탄화
   */
  static flatten(arr: any[], depth: number = 1): any[] {
    const result: any[] = [];

    const flatten_helper = (arr: any[], d: number) => {
      for (let i = 0; i < arr.length; i++) {
        if (Array.isArray(arr[i]) && d > 0) {
          flatten_helper(arr[i], d - 1);
        } else {
          result.push(arr[i]);
        }
      }
    };

    flatten_helper(arr, depth);
    return result;
  }

  /**
   * unique(arr) - 중복 제거
   */
  static unique(arr: any[]): any[] {
    const seen = new Set<any>();
    const result: any[] = [];

    for (let i = 0; i < arr.length; i++) {
      if (!seen.has(arr[i])) {
        seen.add(arr[i]);
        result.push(arr[i]);
      }
    }

    return result;
  }

  /**
   * zip(...arrays) - 여러 배열을 짝맞춰 합치기
   */
  static zip(...arrays: any[][]): any[] {
    if (arrays.length === 0) return [];

    const minLength = Math.min(...arrays.map((a) => a.length));
    const result: any[] = [];

    for (let i = 0; i < minLength; i++) {
      const tuple: any[] = [];
      for (let j = 0; j < arrays.length; j++) {
        tuple.push(arrays[j][i]);
      }
      result.push(tuple);
    }

    return result;
  }

  /**
   * range(start, end, step) - 숫자 범위 배열 생성
   */
  static range(start: number, end: number, step: number = 1): number[] {
    const result: number[] = [];
    if (step > 0) {
      for (let i = start; i < end; i += step) {
        result.push(i);
      }
    } else if (step < 0) {
      for (let i = start; i > end; i += step) {
        result.push(i);
      }
    }
    return result;
  }

  /**
   * sum(arr) - 배열 요소의 합
   */
  static sum(arr: any[]): number {
    let total = 0;
    for (let i = 0; i < arr.length; i++) {
      if (typeof arr[i] === "number") {
        total += arr[i];
      }
    }
    return total;
  }

  /**
   * average(arr) - 배열 요소의 평균
   */
  static average(arr: any[]): number {
    if (arr.length === 0) return 0;
    return this.sum(arr) / arr.length;
  }

  /**
   * min(arr) - 최솟값
   */
  static min(arr: any[]): number {
    if (arr.length === 0) return NaN;
    let min = arr[0];
    for (let i = 1; i < arr.length; i++) {
      if (typeof arr[i] === "number" && arr[i] < min) {
        min = arr[i];
      }
    }
    return min;
  }

  /**
   * max(arr) - 최댓값
   */
  static max(arr: any[]): number {
    if (arr.length === 0) return NaN;
    let max = arr[0];
    for (let i = 1; i < arr.length; i++) {
      if (typeof arr[i] === "number" && arr[i] > max) {
        max = arr[i];
      }
    }
    return max;
  }
}
